-- PENDING MANUAL REVIEW: tested on an isolated database branch only. NOT applied to production.
-- Do not apply until the six product and pack questions have been answered.
-- Manually reviewed labelled product identities. Not automatic barcode matching or buying approval.
DO $$
DECLARE r record; o record; c record; m record; master_id bigint;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"asin": "B00535ZIY0", "supplier": "Sweet & Glory", "sku": "COFF002", "supplier_ean": "", "supplier_title": "Nestle Coffee Crisp 50g (CAN)", "case_qty": 48, "unit_size": "50g", "master_title": "Nestle Coffee Crisp Original 50g Bar (Canada)", "brand": "Nestle", "variant": "Coffee Crisp Original", "candidate_title": "Canada Candy Coffee Crisp Chocolate Bar 4 x 50g Bars. Imported from Canada.", "pack_qty": 4, "reuse_master": null, "listing_ean": "", "master_ean": "0059800094214", "upc": "059800094214", "evidence": {"method": "labelled_product_review_batch4_2026_10_25", "identity_basis": "Manual review of explicit brand, variant, physical unit size, form and Amazon sell quantity; not an exact supplier-barcode claim", "amazon_sell_pack_qty": 4, "supplier_case_qty": 48, "supplier_offer_id": "544", "verifiedSupplierProductId": "COFF002", "verifiedSupplier": "Sweet & Glory", "amazon_url": "https://www.amazon.co.uk/dp/B00535ZIY0", "amazon_captured_at": "2026-10-25T23:15:12.402824+00:00", "amazon_labelled_facts": {"Brand Name": "Coffee Crisp", "UPC": "059800094214", "Container Type": "Bar", "ASIN": "B00535ZIY0", "Unit Count": "200.0 gram", "Size": "200 gram", "Number of Pieces": "4", "Item Weight": "50 g", "Item Package Quantity": "1"}, "supplier_source": "https://sweetandglory.com/brands/n-p/nestle-wholesale-uk", "supplier_record_last_seen_at": "2026-10-24T18:57:59.720Z", "review_notes": "Original Canadian Coffee Crisp, four 50g bars per sale (200g total): title, Number of Pieces 4 and Unit Count 200g agree. Supplier COFF002 is 48 individual 50g bars, yielding 12 Amazon four-packs. Labelled UPC belongs to underlying bar, not an assembled four-pack. Supplier pricing/delivery still require commercial validation.", "commercial_approved": false, "supplier_barcode_verified": false, "amazon_barcode_scope": "underlying retail unit; assembled multipack barcode unknown", "amazon_upc": "059800094214"}}, {"asin": "B086RVCG7B", "supplier": "Sweet & Glory", "sku": "DUDS001", "supplier_ean": "", "supplier_title": "Milk Duds Theatre 141g", "case_qty": 12, "unit_size": "141g", "master_title": "Milk Duds Original Theatre Box 141g", "brand": "Hershey''s", "variant": "Milk Duds Original", "candidate_title": "x 2 Box of HERSHEY''S Milk Duds Theatre Box 141g Original", "pack_qty": 2, "reuse_master": null, "listing_ean": "", "master_ean": "0010700021526", "upc": "010700021526", "evidence": {"method": "labelled_product_review_batch4_2026_10_25", "identity_basis": "Manual review of explicit brand, variant, physical unit size, form and Amazon sell quantity; not an exact supplier-barcode claim", "amazon_sell_pack_qty": 2, "supplier_case_qty": 12, "supplier_offer_id": "155", "verifiedSupplierProductId": "DUDS001", "verifiedSupplier": "Sweet & Glory", "amazon_url": "https://www.amazon.co.uk/dp/B086RVCG7B", "amazon_captured_at": "2026-10-25T23:15:12.422719+00:00", "amazon_labelled_facts": {"Brand Name": "Hershey''s", "Flavour": "Caramel", "UPC": "010700021526", "Container Type": "Box", "ASIN": "B086RVCG7B", "Unit Count": "282.0 gram", "Size": "141g", "Number of Pieces": "2", "Item Package Quantity": "2"}, "supplier_source": "https://sweetandglory.com/brands/i-m/milk-duds-wholesale-uk", "supplier_record_last_seen_at": "2026-10-24T18:57:59.720Z", "review_notes": "Two original 141g Milk Duds theatre boxes per sale: title x2, package quantity 2, pieces 2 and unit count 282g agree. Supplier 12-box case yields six two-packs. Labelled UPC is an underlying retail box code; no assembled-pack EAN assigned.", "commercial_approved": false, "supplier_barcode_verified": false, "amazon_barcode_scope": "underlying retail unit; assembled multipack barcode unknown", "amazon_upc": "010700021526"}}, {"asin": "B004283KSA", "supplier": "Sweet & Glory", "sku": "JELL008", "supplier_ean": "", "supplier_title": "Jell-O Watermelon 85g", "case_qty": 24, "unit_size": "85g", "master_title": "Jell-O Watermelon 85g", "brand": "Jell-O", "variant": "Wat