6_10_25", "identity_basis": "Manual review of explicit brand, variant, physical unit size, form and Amazon sell quantity; not an exact supplier-barcode claim", "amazon_sell_pack_qty": 3, "supplier_case_qty": 12, "supplier_offer_id": "534", "verifiedSupplierProductId": "NERD056", "verifiedSupplier": "Sweet & Glory", "amazon_url": "https://www.amazon.co.uk/dp/B08HQL7NCM", "amazon_captured_at": "2026-10-25T23:15:21.586942+00:00", "amazon_labelled_facts": {"Brand Name": "Nerds", "Flavour": "Fruity", "Container Type": "Packet", "UPC": "079200051228", "ASIN": "B08HQL7NCM", "Unit Count": "255 gram", "Number of Items": "3", "Item Weight": "3 Ounces", "Item Package Quantity": "1", "Number of Pieces": "3", "Size": "85 g (Pack of 3)"}, "supplier_source": "https://sweetandglory.com/brands/n-p/nerds-wholesale-uk", "supplier_record_last_seen_at": "2026-10-24T18:57:59.720Z", "review_notes": "Three 85g Gummy Clusters packets per sale, 255g total: title, Size, Number of Items 3 and unit count agree. Match only NERD056 peg bag, not NERD023 theatre box or NERD026 share pouch. Keep the existing review-only theatre-box master separate. Supplier barcode unknown; individual Amazon UPC is not an assembled three-pack EAN.", "commercial_approved": false, "supplier_barcode_verified": false, "amazon_barcode_scope": "underlying retail unit; assembled multipack barcode unknown", "amazon_upc": "079200051228"}}, {"asin": "B0FTPY8RLZ", "supplier": "Sweet & Glory", "sku": "REES165", "supplier_ean": "", "supplier_title": "Reese'' Pieces Peg Bag 136g", "case_qty": 12, "unit_size": "136g", "master_title": "Reese''s Pieces Peanut Butter Peg Bag 136g", "brand": "Reese''s", "variant": "Pieces Peanut Butter", "candidate_title": "REESE''S PIECES PEG BAG 136g 4.8 OZ", "pack_qty": 1, "reuse_master": null, "listing_ean": "0034000116430", "master_ean": "0034000116430", "upc": "034000116430", "evidence": {"method": "labelled_product_review_batch4_2026_10_25", "identity_basis": "Manual review of explicit brand, variant, physical unit size, form and Amazon sell quantity; not an exact supplier-barcode claim", "amazon_sell_pack_qty": 1, "supplier_case_qty": 12, "supplier_offer_id": "611", "verifiedSupplierProductId": "REES165", "verifiedSupplier": "Sweet & Glory", "amazon_url": "https://www.amazon.co.uk/dp/B0FTPY8RLZ", "amazon_captured_at": "2026-10-25T23:15:26.310330+00:00", "amazon_labelled_facts": {"Brand Name": "Reese''s", "Flavour": "Peanut Butter", "UPC": "034000116430", "Container Type": "Bag", "ASIN": "B0FTPY8RLZ", "Unit Count": "136.0 gram", "Size": "Full Size", "Number of Pieces": "1", "Number of Items": "1", "Item Weight": "136 Grams", "Item Package Quantity": "1"}, "supplier_source": "https://sweetandglory.com/brands/q-s/reeses-wholesale-uk", "supplier_record_last_seen_at": "2026-10-24T18:57:59.720Z", "review_notes": "One 136g Reese Pieces peanut butter peg bag: exact brand/product format and weight match supplier REES165. Number of Items and Pieces both 1. Supplier retail barcode remains unknown.", "commercial_approved": false, "supplier_barcode_verified": false, "amazon_barcode_scope": "single retail unit", "amazon_upc": "034000116430"}}, {"asin": "B004I8EUBA", "supplier": "Americatessen", "sku": "HEINZ-61050-12", "supplier_ean": "", "supplier_title": "Heinz Chili Sauce (340g)", "case_qty": 12, "unit_size": "340g", "master_title": "Heinz Chili Sauce 340g Bottle", "brand": "Heinz", "variant": "Chili Sauce", "candidate_title": "HEINZ CHILI SAUCE 1 x 340g BOTTLE AMERICAN IMPORT", "pack_qty": 1, "reuse_master": null, "listing_ean": "", "master_ean": "", "upc": "", "evidence": {"method": "labelled_product_review_batch4_2026_10_25", "identity_basis": "Manual review of explicit brand, variant, physical unit size, form and Amazon sell quantity; not an exact supplier-barcode claim", "amazon_sell_pack_qty": 1, "supplier_case_qty": 12, "supplier_offer_id": "11005", "verifiedSupplierProductId": "HEINZ-61050-12", "verifiedSupplier": "Americatessen", "amazon_url": "https://www.amazon.co.uk/dp/B004I8EUBA", "amazon_captured_at": "2026-10-25T23:15:30.946787+00:00", "amazon_labelled_facts": {"Flavour": "Chili", "Brand Name": "HEINZ", "Container Type": "Bottle", "ASIN": "B004I8EUBA", "Item Weight": "12 Ounces", "Unit Count": "340 gram", "Number of Items": "1", "Number of Pieces": "1", "Size": "7.8 x 6.9 x 22.8 cm"}, "supplier_source": "https://www.americatessen.com/american-grocery-supplier-american-wholesalers-uk", "supplier_record_last_seen_at": "2026-10-24T19:03:42.922Z", "review_notes": "One Heinz Chili Sauce 340g bottle, explicitly American import: title, flavour, bottle container, Unit Count 340g, Number of Items 1 and 12oz net size agree. Dimensions mistakenly supplied as Size are not net unit weight. No barcode exposed in fresh capture; supplier cost remains missing and availability historical.", "commercial_approved": false, "supplier_barcode_verified": false, "amazon_barcode_scope": "single retail unit"}}]'::jsonb) AS t(asin text,supplier text,sku text,supplier_ean text,supplier_title text,case_qty integer,unit_size text,master_title text,brand text,variant text,candidate_title text,pack_qty integer,reuse_master bigint,listing_ean text,master_ean text,upc text,evidence jsonb)
 LOOP
  SELECT so.*,s.name supplier INTO STRICT o FROM supplier_offers so JOIN suppliers s ON s.id=so.supplier_id WHERE s.name=r.supplier AND so.supplier_product_id=r.sku;
  SELECT * INTO STRICT c FROM amazon_catalogue_candidates WHERE asin=r.asin;
  IF NOT o.is_active OR o.product<>r.supplier_title OR coalesce(o.ean,'')<>r.supplier_ean OR o.size<>r.unit_size OR o.case_qty<>r.case_qty OR c.title<>r.candidate_title THEN RAISE EXCEPTION 'Evidence changed: %',r.asin; END IF;
  IF c.match_status NOT IN ('unmatched','verified') OR (c.match_status='verified' AND coalesce(c.match_evidence->>'method','')<>'labelled_product_review_batch4_2026_10_25') THEN RAISE EXCEPTION 'Existing decision requires review: %',r.asin; END IF;
  IF r.upc<>'' AND EXISTS(SELECT 1 FROM unnest(ARRAY[c.ean,c.upc,c.gtin]) code WHERE coalesce(code,'')<>'' AND lpad(code,14,'0')<>lpad(r.upc,14,'0')) THEN RAISE EXCEPTION 'Existing barcode conflict: %',r.asin; END IF;
  master_id:=r.reuse_master;
  IF master_id IS NOT NULL THEN
   SELECT * INTO STRICT m FROM master_product_identities WHERE id=master_id;
   IF m.product_name<>r.master_title OR m.unit_size<>r.unit_size OR m.status<>'verified' THEN RAISE EXCEPTION 'Reused master changed: %',r.asin; END IF;
  ELSE
   IF (SELECT count(*) FROM master_product_identities WHERE asin=r.asin)>1 THEN RAISE EXCEPTION 'Duplicate masters: %',r.asin; END IF;
   SELECT id INTO master_id FROM master_product_identities WHERE asin=r.asin;
   IF master_id IS NULL THEN
    INSERT INTO master_product_identities(product_name,brand,variant,size,unit_size,ean,asin,status,canonical_key)
    VALUES(r.master_title,r.brand,r.variant,r.unit_size,r.unit_size,r.master_ean,r.asin,'verified',lower(r.brand||'|'||r.variant||'|'||r.unit_size)) RETURNING id INTO master_id;
   END IF;
  END IF;
  IF EXISTS(SELECT 1 FROM product_identity_offers WHERE supplier=r.supplier AND supplier_offer_id=r.sku AND identity_id<>master_id) OR EXISTS(SELECT 1 FROM amazon_product_listings WHERE marketplace='UK' AND asin=r.asin AND (identity_id<>master_id OR pack_qty<>r.pack_qty)) THEN RAISE EXCEPTION 'Conflicting relationship: %',r.asin; END IF;
  INSERT INTO product_identity_offers(identity_id,supplier,supplier_offer_id,match_score,match_status,match_reason)
  VALUES(master_id,r.supplier,r.sku,100,'verified','2026-10-25 labelled product review: '||r.evidence::text) ON CONFLICT(supplier,supplier_offer_id) DO NOTHING;
  INSERT INTO amazon_product_listings(identity_id,asin,ean,pack_qty,unit_size,title,marketplace,status)
  VALUES(master_id,r.asin,r.listing_ean,r.pack_qty,r.unit_size,c.title,'UK','verified') ON CONFLICT(marketplace,asin) DO NOTHING;
  UPDATE amazon_catalogue_candidates SET match_status='verified',matched_master_identity_id=master_id,matched_supplier_offer_id=o.id,match_score=100,upc=coalesce(nullif(upc,''),nullif(r.upc,'')),match_evidence=coalesce(match_evidence,'{}'::jsonb)||r.evidence,updated_at=now() WHERE asin=r.asin AND match_status='unmatched';
 END LOOP;
END $$;
